def evolved_fsdp_prefetch(shards, M, N_LAYERS, rank, world_size,
                          num_devices, cores_per_device, xm, torch, num_nodes=1):
    """gather each layer once (weights shared across microbatches), reuse across M."""
    gathered = []
    for L in range(N_LAYERS):
        gathered.append(xm.all_gather(shards[0][L], dim=-1))
    outs = []
    for m in range(M):
        outs.append([gathered[L] for L in range(N_LAYERS)])
    return outs
